d.append({'id':'L85A','title':'Recovered coefficient ledger v0.85 and scoped normalization preflight','group':'Governance and ledgers','status':'INVENTORY PASS / O13 CORRECTION PROPOSED / EXIT-03 HOLD','note':'723 unique objects; constructor audit, no physical promotion. QPB1 eta_A=2/1 remains quarantined.','url':'/evidence/ledger-recovery/','local':'/sources/ledger-recovery-v0.1/library_LEDGER_v0.85.json','sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'size_bytes':source.stat().st_size,'content':(capture/'REPORT.md').read_text()})
